// A month calendar: seven columns, today ringed, dots for busy days.
const busy = { 4: 1, 8: 2, 12: 3, 15: 1, 19: 2, 22: 1, 27: 2, 29: 1 }

export function get(app) {
  const first = 4 // March 2024 starts on a Friday (Monday = 0)
  const days = []
  for (let i = 0; i < first; i++) days.push(null)
  for (let d = 1; d <= 31; d++) days.push(d)
  while (days.length % 7) days.push(null)
  return (
    <div className="flex flex-col p-6 gap-3 bg-white text-slate-800">
      <div className="flex items-end justify-between">
        <div className="flex items-end gap-3">
          <span className="text-4xl font-bold">March</span>
          <span className="text-4xl text-slate-400">2024</span>
        </div>
        <span className="text-lg text-rose-500 font-semibold">Spring starts on the 20th</span>
      </div>
      <div className="grid grid-cols-7 gap-1 text-center">
        {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map((d) => (
          <span className="text-sm uppercase text-slate-400 font-semibold">{d}</span>
        ))}
      </div>
      <div className="flex-1 grid grid-cols-7 gap-1">
        {days.map((d, i) => d === null ? <div /> : (
          <div className={`flex flex-col items-center justify-center gap-1 rounded-lg ${i % 7 >= 5 ? 'bg-slate-50' : ''}`}>
            <span className={`text-xl w-10 h-10 flex items-center justify-center rounded-full ${d === 12 ? 'bg-rose-500 text-white font-bold' : ''}`}>{d}</span>
            <div className="flex gap-1 h-2">
              {Array.from({ length: busy[d] || 0 }).map(() => <div className="w-2 h-2 rounded-full bg-sky-400" />)}
            </div>
          </div>
        ))}
      </div>
    </div>
  )
}
